    #[must_use]
    pub const fn name(self) -> &'static str {
        self.0.descriptor.name
    }

    /// The field whose key is exactly `name`.
    #[must_use]
    pub fn from_name(name: &str) -> Option<Self> {
        Self::ALL.into_iter().find(|id| id.name() == name)
    }
